using System;
using System.Collections;
using System.Diagnostics;

namespace MeteoStanice
{
    /// <summary>
    /// Represents one operational event generated by the station.
    /// </summary>
    public sealed class NanoDeviceEvent
    {
        // Station that produced the event.
        public string StationId { get; set; }
        // Monotonic event sequence number.
        public int SequenceNumber { get; set; }
        // Time when the event occurred.
        public DateTime OccurredAt { get; set; }
        // Event severity.
        public DeviceEventSeverity Severity { get; set; }
        // Event subsystem category.
        public DeviceEventCategory Category { get; set; }
        // Stable machine-readable event code.
        public DeviceEventCode Code { get; set; }
        // Component that produced the event.
        public string Component { get; set; }
        // Short diagnostic message.
        public string Message { get; set; }
    }

    /// <summary>
    /// Stores device events in a fixed-size RAM queue.
    /// </summary>
    public sealed class NanoDeviceEventQueue
    {
        private readonly Queue _items;
        private readonly int _capacity;

        /// <summary>
        /// Creates a device event queue with fixed capacity.
        /// </summary>
        public NanoDeviceEventQueue(int capacity)
        {
            _items = new Queue();
            _capacity = capacity;
        }

        // Number of queued events.
        public int Count
        {
            get
            {
                return _items.Count;
            }
        }

        /// <summary>
        /// Adds one event when there is free capacity.
        /// </summary>
        public bool Enqueue(NanoDeviceEvent deviceEvent)
        {
            if (deviceEvent == null || _items.Count >= _capacity)
            {
                return false;
            }

            _items.Enqueue(deviceEvent);
            return true;
        }

        /// <summary>
        /// Reads the oldest event without removing it.
        /// </summary>
        public bool TryPeek(out NanoDeviceEvent deviceEvent)
        {
            if (_items.Count == 0)
            {
                deviceEvent = null;
                return false;
            }

            deviceEvent = (NanoDeviceEvent)_items.Peek();
            return true;
        }

        /// <summary>
        /// Removes and returns the oldest event.
        /// </summary>
        public bool TryDequeue(out NanoDeviceEvent deviceEvent)
        {
            if (_items.Count == 0)
            {
                deviceEvent = null;
                return false;
            }

            deviceEvent = (NanoDeviceEvent)_items.Dequeue();
            return true;
        }
    }

    /// <summary>
    /// Creates device events and suppresses repeated active error codes.
    /// </summary>
    public sealed class NanoDeviceEventService
    {
        private readonly NanoDeviceEventQueue _queue;
        private int _sequenceNumber;
        private bool _hasActiveCode;
        private DeviceEventCode _activeCode;

        /// <summary>
        /// Creates event service backed by a device event queue.
        /// </summary>
        public NanoDeviceEventService(NanoDeviceEventQueue queue)
        {
            _queue = queue;
        }

        /// <summary>
        /// Reports one event unless the same error code is already active.
        /// </summary>
        public bool Report(string stationId, DeviceEventSeverity severity, DeviceEventCategory category, DeviceEventCode code, string component, string message)
        {
            if (_hasActiveCode && _activeCode == code)
            {
                return false;
            }

            _sequenceNumber++;
            _hasActiveCode = true;
            _activeCode = code;

            NanoDeviceEvent deviceEvent = new NanoDeviceEvent();
            deviceEvent.StationId = stationId;
            deviceEvent.SequenceNumber = _sequenceNumber;
            deviceEvent.OccurredAt = new DateTime(2026, 1, 1, 10, 0, 0).AddSeconds(_sequenceNumber);
            deviceEvent.Severity = severity;
            deviceEvent.Category = category;
            deviceEvent.Code = code;
            deviceEvent.Component = component;
            deviceEvent.Message = message;

            if (!_queue.Enqueue(deviceEvent))
            {
                return false;
            }

            Debug.WriteLine("Event #" + deviceEvent.SequenceNumber + " " + deviceEvent.Code.ToString() + ": " + deviceEvent.Message);
            return true;
        }

        /// <summary>
        /// Clears active suppression after a component recovery.
        /// </summary>
        public void ClearActive()
        {
            _hasActiveCode = false;
        }
    }

    /// <summary>
    /// Uploads queued device events through the simulated upload path.
    /// </summary>
    public sealed class NanoDeviceEventUploadService
    {
        private readonly NanoDeviceEventQueue _queue;
        private readonly NanoUploadClient _client;

        /// <summary>
        /// Creates upload service for queued device events.
        /// </summary>
        public NanoDeviceEventUploadService(NanoDeviceEventQueue queue, NanoUploadClient client)
        {
            _queue = queue;
            _client = client;
        }

        /// <summary>
        /// Uploads at most one pending device event.
        /// </summary>
        public bool TryUploadOne()
        {
            NanoDeviceEvent deviceEvent;
            if (!_queue.TryPeek(out deviceEvent))
            {
                return false;
            }

            if (!_client.UploadEvent(deviceEvent))
            {
                return false;
            }

            _queue.TryDequeue(out deviceEvent);
            return true;
        }

        /// <summary>
        /// Uploads pending events until the queue is empty, an upload fails, or the limit is reached.
        /// </summary>
        public int TryUploadPending(int maxItems)
        {
            int uploaded = 0;
            while (uploaded < maxItems && TryUploadOne())
            {
                uploaded++;
            }

            return uploaded;
        }
    }
}
